export const QUERY = 'ff:'
export const matches = (entries: Entry[], query: string) => {
  const q = query.trim().toLowerCase()
  return entries.filter(
    ([key, value]) => !q || key.toLowerCase().includes(q) || value.toLowerCase().includes(q),
  )
}
